import{_ as e,c as i,o as r,a0 as t}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Introduksjon til mentalt spill – deltakerguide","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/no/participant-guide.md","filePath":"public/downloads/no/participant-guide.md"}');const l=e({name:"public/downloads/no/participant-guide.md"},[["render",function(e,n,l,a,s,o){return r(),i("div",null,[...n[0]||(n[0]=[t('<h1 id="introduksjon-til-mentalt-spill-–-deltakerguide" tabindex="-1">Introduksjon til mentalt spill – deltakerguide <a class="header-anchor" href="#introduksjon-til-mentalt-spill-–-deltakerguide" aria-label="Permalink to &quot;Introduksjon til mentalt spill – deltakerguide&quot;">​</a></h1><p><strong>Petanque-akademiet</strong><em>Utvikling av elitespillere</em></p><hr><h2 id="velkomst" tabindex="-1">Velkomst <a class="header-anchor" href="#velkomst" aria-label="Permalink to &quot;Velkomst&quot;">​</a></h2><p>I dag skal du lære praktiske mentale spillteknikker for å forbedre petanque-prestasjonen din.</p><h3 id="hva-du-vil-lære" tabindex="-1">Hva du vil lære <a class="header-anchor" href="#hva-du-vil-lære" aria-label="Permalink to &quot;Hva du vil lære&quot;">​</a></h3><ul><li>Hvorfor mental trening er viktig for elitespillere</li><li>Forskjellen mellom &quot;teknisk modus&quot; og &quot;flytmodus&quot;</li><li>Hvordan gjenkjenne og håndtere din indre kritiker</li><li>Enkle teknikker for trykkhåndtering</li><li>En grunnleggende rutine før inntak</li></ul><hr><h2 id="sone-flyttilstanden" tabindex="-1">Sone-/flyttilstanden <a class="header-anchor" href="#sone-flyttilstanden" aria-label="Permalink to &quot;Sone-/flyttilstanden&quot;">​</a></h2><h3 id="hva-er-flyt" tabindex="-1">Hva er flyt? <a class="header-anchor" href="#hva-er-flyt" aria-label="Permalink to &quot;Hva er flyt?&quot;">​</a></h3><p>Flyt er den magiske tilstanden der:</p><ul><li>Alt føles uanstrengt</li><li>Tiden ser ut til å sakte ned</li><li>Du tenker ikke, bare leker</li><li>Teknikken din fungerer perfekt</li></ul><h3 id="to-sinnstilstander" tabindex="-1">To sinnstilstander <a class="header-anchor" href="#to-sinnstilstander" aria-label="Permalink to &quot;To sinnstilstander&quot;">​</a></h3><p><strong>Planleggingsmodus (Analytisk)</strong></p><ul><li>Analysere terrenget</li><li>Velge strategien din</li><li>Å bestemme seg for skuddet</li><li>Vurdering av risikoer</li></ul><p><strong>Utførelsesmodus (flyt)</strong></p><ul><li>Å stole på kroppen din</li><li>Tenker ikke på teknikk</li><li>Fokus i nåtiden</li><li>Automatisk utførelse</li></ul><h3 id="bryteren" tabindex="-1">Bryteren <a class="header-anchor" href="#bryteren" aria-label="Permalink to &quot;Bryteren&quot;">​</a></h3><p>Nøkkelferdigheten: <strong>bytte fra planleggings- til utførelsesmodus</strong></p><p><strong>Før opptaket:</strong> Analyser, planlegg, bestem deg <strong>Under opptaket:</strong> Tillit, flyt, utførelse</p><hr><h2 id="den-indre-kritikeren-vs-indre-coach" tabindex="-1">Den indre kritikeren vs. indre coach <a class="header-anchor" href="#den-indre-kritikeren-vs-indre-coach" aria-label="Permalink to &quot;Den indre kritikeren vs. indre coach&quot;">​</a></h2><h3 id="din-indre-kritiker-sier" tabindex="-1">Din indre kritiker sier: <a class="header-anchor" href="#din-indre-kritiker-sier" aria-label="Permalink to &quot;Din indre kritiker sier:&quot;">​</a></h3><ul><li>&quot;Det var forferdelig!&quot;</li><li>&quot;Du roter alltid til under press&quot;</li><li>«Alle ser deg mislykkes»</li><li>&quot;Du er ikke god nok&quot;</li></ul><h3 id="din-indre-coach-sier" tabindex="-1">Din indre coach sier: <a class="header-anchor" href="#din-indre-coach-sier" aria-label="Permalink to &quot;Din indre coach sier:&quot;">​</a></h3><ul><li>&quot;Hva kan jeg lære av dette?&quot;</li><li>&quot;Neste sjanse, ny start&quot;</li><li>«Jeg har tatt dette bildet før»</li><li>&quot;Stol på prosessen&quot;</li></ul><h3 id="reframing-øvelse" tabindex="-1">Reframing-øvelse <a class="header-anchor" href="#reframing-øvelse" aria-label="Permalink to &quot;Reframing-øvelse&quot;">​</a></h3><p>Når du legger merke til din indre kritiker:</p><ol><li><strong>Pause</strong> - Gjenkjenn den kritiske tanken</li><li><strong>Omformuler</strong> – Hva ville treneren din sagt?</li><li><strong>Tilbakestill</strong> - Ta 3 åndedrag</li><li><strong>Refokuser</strong> - Neste bilde</li></ol><hr><h2 id="praktiske-verktøy" tabindex="-1">Praktiske verktøy <a class="header-anchor" href="#praktiske-verktøy" aria-label="Permalink to &quot;Praktiske verktøy&quot;">​</a></h2><h3 id="_3-pust-tilbakestilling" tabindex="-1">3-pust-tilbakestilling <a class="header-anchor" href="#_3-pust-tilbakestilling" aria-label="Permalink to &quot;3-pust-tilbakestilling&quot;">​</a></h3><p>Bruk dette etter feil eller når du føler deg presset:</p><ol><li><strong>Pustepust 1:</strong> Legg merke til spenningen (hvor kjenner du den?)</li><li><strong>Pustegang 2:</strong> Slipp spenningen (slipp den løs)</li><li><strong>Pustedrag 3:</strong> Fokuser på nåtiden (dette bildet, dette øyeblikket)</li></ol><h3 id="rutine-før-inntak" tabindex="-1">Rutine før inntak <a class="header-anchor" href="#rutine-før-inntak" aria-label="Permalink to &quot;Rutine før inntak&quot;">​</a></h3><p>Skap konsistens med en enkel rutine:</p><ol><li><strong>Visualiser</strong> - Se bildet for deg</li><li><strong>Pust</strong> - Ett dypt åndedrag</li><li><strong>Anker</strong> - Berør kulen din, kjenn vekten</li><li><strong>Utfør</strong> - Stol på og kast</li></ol><h3 id="protokoll-for-feilretting" tabindex="-1">Protokoll for feilretting <a class="header-anchor" href="#protokoll-for-feilretting" aria-label="Permalink to &quot;Protokoll for feilretting&quot;">​</a></h3><p>Etter et dårlig skudd:</p><ol><li><strong>Erkjennelse</strong> - &quot;Det gikk ikke som planlagt&quot;</li><li><strong>Utgivelse</strong> - Fysisk tilbakestilling (riste det av seg, gå)</li><li><strong>Refokuser</strong> - «Neste skudd er en ny mulighet»</li><li><strong>Utfør</strong> - Stol på rutinen din</li></ol><hr><h2 id="din-handlingsplan" tabindex="-1">Din handlingsplan <a class="header-anchor" href="#din-handlingsplan" aria-label="Permalink to &quot;Din handlingsplan&quot;">​</a></h2><h3 id="denne-uken" tabindex="-1">Denne uken <a class="header-anchor" href="#denne-uken" aria-label="Permalink to &quot;Denne uken&quot;">​</a></h3><p>Velg ÉN teknikk å øve på:</p><ul><li>[] 3-Åndrestilling etter hver feil</li><li>[] Rutine før skudd på hvert kast</li><li>[] Omformuler én indre kritiker-tanke per økt</li><li>[] Øv på å bytte fra planleggings- til utførelsesmodus</li></ul><h3 id="spor-fremgangen-din" tabindex="-1">Spor fremgangen din <a class="header-anchor" href="#spor-fremgangen-din" aria-label="Permalink to &quot;Spor fremgangen din&quot;">​</a></h3><p>Merknad:</p><ul><li>Når føler du deg mest i flyt?</li><li>Hva trigger din indre kritiker?</li><li>Hvilken teknikk hjelper deg mest?</li><li>Hvordan endrer prestasjonene dine seg?</li></ul><hr><h2 id="ressurser-og-neste-steg" tabindex="-1">Ressurser og neste steg <a class="header-anchor" href="#ressurser-og-neste-steg" aria-label="Permalink to &quot;Ressurser og neste steg&quot;">​</a></h2><h3 id="fortsett-a-lære" tabindex="-1">Fortsett å lære <a class="header-anchor" href="#fortsett-a-lære" aria-label="Permalink to &quot;Fortsett å lære&quot;">​</a></h3><ul><li><strong>Sonen</strong> – Dykk dypt inn i flyttilstander</li><li><strong>Mental styrke</strong> - Avansert presshåndtering</li><li><strong>Målmal</strong> – Strukturer utviklingen din</li><li><strong>Mal for dagbok</strong> – Spor fremgangen din</li></ul><h3 id="øv-daglig" tabindex="-1">Øv daglig <a class="header-anchor" href="#øv-daglig" aria-label="Permalink to &quot;Øv daglig&quot;">​</a></h3><ul><li>5 minutter med bevisst pusting</li><li>Visualiser vellykkede bilder</li><li>Øv på rutinen din før inntak</li><li>Omformuler negative tanker</li></ul><hr><h2 id="viktige-konklusjoner" tabindex="-1">Viktige konklusjoner <a class="header-anchor" href="#viktige-konklusjoner" aria-label="Permalink to &quot;Viktige konklusjoner&quot;">​</a></h2><ol><li><strong>Flytningstilstand er tilgjengelig</strong> – Du kan lære å legge den inn mer konsekvent</li><li><strong>Din indre stemme teller</strong> - Coach deg selv, ikke kritiser</li><li><strong>Enkle verktøy fungerer</strong> - 3 åndedrag, en rutine, en tilbakestilling</li><li><strong>Øvelse er nøkkelen</strong> - Mentale ferdigheter trenger trening, akkurat som tekniske ferdigheter</li></ol><hr><p><strong>Husk:</strong> Mental trening handler ikke om positiv tenkning. Det handler om praktiske teknikker som hjelper deg med å oppnå best mulig ytelse under press.</p><hr><p><em>Besøk carreau.app for flere ressurser</em><em>Pétanque Academy - Elitespillerutvikling</em></p>',61)])])}]]);export{n as __pageData,l as default};
